namespace sv_3dff428ba330408fb85df56906943d78.Services;

public sealed record Recipe(int Id, string Title, string Description, int PrepTimeMinutes);

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> _data = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Spaghetti Carbonara", "Classic Roman pasta with eggs, pecorino, guanciale, and black pepper.", 25),
            new(2, "Margherita Pizza", "Neapolitan pizza with San Marzano tomatoes, mozzarella, and fresh basil.", 45),
            new(3, "Tiramisu", "Layered coffee-soaked ladyfingers with mascarpone cream and cocoa.", 30),
        },
        [2] = new List<Recipe>
        {
            new(4, "Chicken Tikka Masala", "Grilled chicken in a creamy spiced tomato sauce served with naan.", 40),
            new(5, "Palak Paneer", "Fresh spinach purée with cubes of paneer cheese and aromatic spices.", 35),
            new(6, "Biryani", "Fragrant basmati rice layered with marinated meat and caramelized onions.", 60),
        },
        [3] = new List<Recipe>
        {
            new(7, "Tacos al Pastor", "Marinated pork on corn tortillas with pineapple, cilantro, and onion.", 50),
            new(8, "Guacamole", "Fresh avocado mashed with lime, cilantro, jalapeño, and tomato.", 10),
            new(9, "Enchiladas Verdes", "Corn tortillas filled with chicken, topped with tangy tomatillo salsa.", 35),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        // Simulate a slow API call
        await Task.Delay(2000, cancellationToken);

        if (_data.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_3dff428ba330408fb85df56906943d78.Services
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation
@implements IDisposable

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<nav>
    <a href="/recipes/1?sort=@Sort">Italian</a> |
    <a href="/recipes/2?sort=@Sort">Indian</a> |
    <a href="/recipes/3?sort=@Sort">Mexican</a>
</nav>

<div style="margin-top: 0.5rem;">
    Sort:
    <a href="/recipes/@CuisineId?sort=newest">Newest</a> |
    <a href="/recipes/@CuisineId?sort=popular">Popular</a>
    @if (!string.IsNullOrEmpty(Sort))
    {
        <span><strong>(@Sort)</strong></span>
    }
</div>

<hr />

@if (_error is not null)
{
    <div role="alert" style="color: red; border: 1px solid red; padding: 1rem; margin-top: 1rem;">
        <p>@_error</p>
        <button @onclick="Retry">Retry</button>
    </div>
}
else if (_recipes is null && _isLoading)
{
    <p><em>Loading recipes…</em></p>
}
else
{
    @if (_isLoading)
    {
        <p><em>Refreshing…</em></p>
    }

    @if (_recipes is not null)
    {
        <ul>
            @foreach (var recipe in GetSortedRecipes())
            {
                <li>
                    <strong>@recipe.Title</strong> — @recipe.Description
                    <br />
                    <small>Prep time: @recipe.PrepTimeMinutes min</small>
                </li>
            }
        </ul>

        @if (_recipes.Count == 0)
        {
            <p>No recipes found for this cuisine.</p>
        }
    }
}

@code {
    [Parameter] public int CuisineId { get; set; }
    [SupplyParameterFromQuery(Name = "sort")] public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isLoading;
    private string? _error;
    private int _loadedCuisineId;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        // Only reload data when the cuisine changes, not when sort changes
        if (CuisineId == _loadedCuisineId && _recipes is not null)
        {
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request
        CancelPendingRequest();

        _cts = new CancellationTokenSource();
        var cancellationToken = _cts.Token;

        _isLoading = true;
        _error = null;
        _loadedCuisineId = CuisineId;
        StateHasChanged();

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, cancellationToken);

            if (!cancellationToken.IsCancellationRequested)
            {
                _recipes = result;
                _isLoading = false;
            }
        }
        catch (OperationCanceledException)
        {
            // Request was cancelled (user navigated away or changed cuisine) — do nothing
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _isLoading = false;
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _isLoading = false;
            _error = "Something went wrong loading recipes. Please try again.";
        }
    }

    private async Task Retry()
    {
        await LoadRecipesAsync();
    }

    private List<Recipe> GetSortedRecipes()
    {
        if (_recipes is null) return new();

        return Sort?.ToLowerInvariant() switch
        {
            "newest" => _recipes.OrderByDescending(r => r.Id).ToList(),
            "popular" => _recipes.OrderBy(r => r.PrepTimeMinutes).ToList(),
            _ => _recipes,
        };
    }

    private void CancelPendingRequest()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    public void Dispose()
    {
        CancelPendingRequest();
    }
}

